// Forward declaration needed for LaunchContextNoOpDeleter

// Custom deleter for sd::LaunchContext instances that are intentionally leaked
// by the LaunchContext::defaultContext() mechanism.
// This prevents std::shared_ptr from attempting to delete these objects,
// avoiding double-free or invalid memory access issues during shutdown.
@Namespace("sd") public static class LaunchContextNoOpDeleter extends Pointer {
    static { Loader.load(); }
    /** Default native constructor. */
    public LaunchContextNoOpDeleter() { super((Pointer)null); allocate(); }
    /** Native array allocator. Access with {@link Pointer#position(long)}. */
    public LaunchContextNoOpDeleter(long size) { super((Pointer)null); allocateArray(size); }
    /** Pointer cast constructor. Invokes {@link Pointer#Pointer(Pointer)}. */
    public LaunchContextNoOpDeleter(Pointer p) { super(p); }
    private native void allocate();
    private native void allocateArray(long size);
    @Override public LaunchContextNoOpDeleter position(long position) {
        return (LaunchContextNoOpDeleter)super.position(position);
    }
    @Override public LaunchContextNoOpDeleter getPointer(long i) {
        return new LaunchContextNoOpDeleter((Pointer)this).offsetAddress(i);
    }

}

